responsePreview:
This Terraform configuration creates an AWS S3 bucket named `example-bucket` with Object Lock enabled at bucket creation time. It enables bucket versioning, which is required for S3 Object Lock, and configures a default Object Lock rule using **COMPLIANCE** mode with a retention period of **30 days** for all new objects placed in the bucket.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "example" {
  bucket              = "example-bucket"
  object_lock_enabled = true
}

resource "aws_s3_bucket_versioning" "example" {
  bucket = aws_s3_bucket.example.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_object_lock_configuration" "example" {
  bucket = aws_s3_bucket.example.id

  rule {
    default_retention {
      mode = "COMPLIANCE"
      days = 30
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.example
  ]
}
```
